"""Unified message and response types shared across all LLM providers."""

from __future__ import annotations

import uuid
from dataclasses import dataclass, field
from enum import Enum
from typing import Any


class Role(str, Enum):
    SYSTEM = "system"
    USER = "user"
    ASSISTANT = "assistant"
    TOOL = "tool"


@dataclass
class ToolCall:
    """A request from the model to invoke a tool."""

    name: str
    arguments: dict[str, Any]
    id: str = field(default_factory=lambda: f"call_{uuid.uuid4().hex[:24]}")


@dataclass
class ToolResult:
    """The outcome of executing a tool call."""

    tool_call_id: str
    content: str
    is_error: bool = False


@dataclass
class Message:
    """A single turn in the conversation.

    - USER / SYSTEM messages carry ``content``.
    - ASSISTANT messages carry ``content`` and optionally ``tool_calls``.
    - TOOL messages carry ``tool_results`` from one tool-execution round.
    """

    role: Role
    content: str = ""
    tool_calls: list[ToolCall] = field(default_factory=list)
    tool_results: list[ToolResult] = field(default_factory=list)

    @classmethod
    def user(cls, content: str) -> Message:
        return cls(role=Role.USER, content=content)

    @classmethod
    def system(cls, content: str) -> Message:
        return cls(role=Role.SYSTEM, content=content)

    @classmethod
    def assistant(cls, content: str = "", tool_calls: list[ToolCall] | None = None) -> Message:
        return cls(role=Role.ASSISTANT, content=content, tool_calls=tool_calls or [])

    @classmethod
    def tool(cls, results: list[ToolResult]) -> Message:
        return cls(role=Role.TOOL, tool_results=results)


@dataclass
class Usage:
    input_tokens: int = 0
    output_tokens: int = 0

    def __add__(self, other: Usage) -> Usage:
        return Usage(
            input_tokens=self.input_tokens + other.input_tokens,
            output_tokens=self.output_tokens + other.output_tokens,
        )


@dataclass
class LLMResponse:
    """Normalized response returned by every provider."""

    content: str = ""
    tool_calls: list[ToolCall] = field(default_factory=list)
    stop_reason: str = "stop"
    usage: Usage = field(default_factory=Usage)

    @property
    def wants_tool_use(self) -> bool:
        return bool(self.tool_calls)

"""Anthropic Claude provider."""

from __future__ import annotations

import os
from typing import Any

from codeagent.core.types import LLMResponse, Message, Role, ToolCall, Usage
from codeagent.llm.base import LLMProvider

DEFAULT_MODEL = "claude-sonnet-4-5"


class AnthropicProvider(LLMProvider):
    name = "anthropic"

    def __init__(
        self,
        model: str = DEFAULT_MODEL,
        api_key: str | None = None,
        max_tokens: int = 8192,
        **client_kwargs: Any,
    ) -> None:
        super().__init__(model=model, max_tokens=max_tokens)
        try:
            from anthropic import AsyncAnthropic
        except ImportError as exc:
            raise ImportError(
                "The 'anthropic' package is required for AnthropicProvider. "
                "Install it with: pip install codeagent[anthropic]"
            ) from exc
        self.client = AsyncAnthropic(
            api_key=api_key or os.environ.get("ANTHROPIC_API_KEY"),
            **client_kwargs,
        )

    async def complete(
        self,
        messages: list[Message],
        tools: list[dict] | None = None,
        system: str | None = None,
        **kwargs: Any,
    ) -> LLMResponse:
        request: dict[str, Any] = {
            "model": self.model,
            "max_tokens": self.max_tokens,
            "messages": self._convert_messages(messages),
        }
        if system:
            request["system"] = system
        if tools:
            request["tools"] = [
                {
                    "name": t["name"],
                    "description": t["description"],
                    "input_schema": t["parameters"],
                }
                for t in tools
            ]
        request.update(kwargs)

        response = await self.client.messages.create(**request)

        content = ""
        tool_calls: list[ToolCall] = []
        for block in response.content:
            if block.type == "text":
                content += block.text
            elif block.type == "tool_use":
                tool_calls.append(
                    ToolCall(id=block.id, name=block.name, arguments=dict(block.input))
                )

        return LLMResponse(
            content=content,
            tool_calls=tool_calls,
            stop_reason=response.stop_reason or "stop",
            usage=Usage(
                input_tokens=response.usage.input_tokens,
                output_tokens=response.usage.output_tokens,
            ),
        )

    @staticmethod
    def _convert_messages(messages: list[Message]) -> list[dict[str, Any]]:
        converted: list[dict[str, Any]] = []
        for msg in messages:
            if msg.role == Role.SYSTEM:
                continue  # system prompt is a top-level API parameter
            if msg.role == Role.USER:
                converted.append({"role": "user", "content": msg.content})
            elif msg.role == Role.ASSISTANT:
                blocks: list[dict[str, Any]] = []
                if msg.content:
                    blocks.append({"type": "text", "text": msg.content})
                blocks.extend(
                    {
                        "type": "tool_use",
                        "id": tc.id,
                        "name": tc.name,
                        "input": tc.arguments,
                    }
                    for tc in msg.tool_calls
                )
                converted.append({"role": "assistant", "content": blocks})
            elif msg.role == Role.TOOL:
                converted.append(
                    {
                        "role": "user",
                        "content": [
                            {
                                "type": "tool_result",
                                "tool_use_id": r.tool_call_id,
                                "content": r.content,
                                "is_error": r.is_error,
                            }
                            for r in msg.tool_results
                        ],
                    }
                )
        return converted

"""OpenAI provider (also covers OpenAI-compatible endpoints)."""

from __future__ import annotations

import json
import os
from typing import Any

from codeagent.core.types import LLMResponse, Message, Role, ToolCall, Usage
from codeagent.llm.base import LLMProvider

DEFAULT_MODEL = "gpt-4o"


class OpenAIProvider(LLMProvider):
    name = "openai"

    def __init__(
        self,
        model: str = DEFAULT_MODEL,
        api_key: str | None = None,
        base_url: str | None = None,
        max_tokens: int = 8192,
        **client_kwargs: Any,
    ) -> None:
        super().__init__(model=model, max_tokens=max_tokens)
        try:
            from openai import AsyncOpenAI
        except ImportError as exc:
            raise ImportError(
                "The 'openai' package is required for OpenAIProvider. "
                "Install it with: pip install codeagent[openai]"
            ) from exc
        self.client = AsyncOpenAI(
            api_key=api_key or os.environ.get("OPENAI_API_KEY"),
            base_url=base_url,
            **client_kwargs,
        )

    async def complete(
        self,
        messages: list[Message],
        tools: list[dict] | None = None,
        system: str | None = None,
        **kwargs: Any,
    ) -> LLMResponse:
        converted = self._convert_messages(messages)
        if system:
            converted.insert(0, {"role": "system", "content": system})

        request: dict[str, Any] = {
            "model": self.model,
            "messages": converted,
            "max_tokens": self.max_tokens,
        }
        if tools:
            request["tools"] = [
                {
                    "type": "function",
                    "function": {
                        "name": t["name"],
                        "description": t["description"],
                        "parameters": t["parameters"],
                    },
                }
                for t in tools
            ]
        request.update(kwargs)

        response = await self.client.chat.completions.create(**request)
        choice = response.choices[0]
        msg = choice.message

        tool_calls = [
            ToolCall(
                id=tc.id,
                name=tc.function.name,
                arguments=json.loads(tc.function.arguments or "{}"),
            )
            for tc in msg.tool_calls or []
        ]

        usage = Usage()
        if response.usage:
            usage = Usage(
                input_tokens=response.usage.prompt_tokens,
                output_tokens=response.usage.completion_tokens,
            )

        return LLMResponse(
            content=msg.content or "",
            tool_calls=tool_calls,
            stop_reason=choice.finish_reason or "stop",
            usage=usage,
        )

    @staticmethod
    def _convert_messages(messages: list[Message]) -> list[dict[str, Any]]:
        converted: list[dict[str, Any]] = []
        for msg in messages:
            if msg.role in (Role.SYSTEM, Role.USER):
                converted.append({"role": msg.role.value, "content": msg.content})
            elif msg.role == Role.ASSISTANT:
                entry: dict[str, Any] = {
                    "role": "assistant",
                    "content": msg.content or None,
                }
                if msg.tool_calls:
                    entry["tool_calls"] = [
                        {
                            "id": tc.id,
                            "type": "function",
                            "function": {
                                "name": tc.name,
                                "arguments": json.dumps(tc.arguments),
                            },
                        }
                        for tc in msg.tool_calls
                    ]
                converted.append(entry)
            elif msg.role == Role.TOOL:
                converted.extend(
                    {
                        "role": "tool",
                        "tool_call_id": r.tool_call_id,
                        "content": r.content,
                    }
                    for r in msg.tool_results
                )
        return converted

"""Provider registry: construct LLM backends from string names."""

from __future__ import annotations

from typing import Any

from codeagent.llm.anthropic import AnthropicProvider
from codeagent.llm.base import LLMProvider
from codeagent.llm.ollama import OllamaProvider
from codeagent.llm.openai import OpenAIProvider

_PROVIDERS: dict[str, type[LLMProvider]] = {
    "anthropic": AnthropicProvider,
    "openai": OpenAIProvider,
    "ollama": OllamaProvider,
}


def register_provider(name: str, provider_cls: type[LLMProvider]) -> None:
    """Register a custom provider class under ``name``."""
    if not (isinstance(provider_cls, type) and issubclass(provider_cls, LLMProvider)):
        raise TypeError("provider_cls must be a subclass of LLMProvider")
    _PROVIDERS[name] = provider_cls


def list_providers() -> list[str]:
    return sorted(_PROVIDERS)


def create_provider(name: str, **kwargs: Any) -> LLMProvider:
    """Instantiate a provider by name.

    Extra keyword arguments (``model``, ``api_key``, ``base_url``, ...) are
    forwarded to the provider constructor.
    """
    try:
        provider_cls = _PROVIDERS[name]
    except KeyError:
        available = ", ".join(list_providers())
        raise ValueError(
            f"Unknown provider {name!r}. Available providers: {available}"
        ) from None
    return provider_cls(**kwargs)

"""Tool abstraction and registry."""

from __future__ import annotations

import json
from abc import ABC, abstractmethod
from typing import Any

from codeagent.core.types import ToolCall, ToolResult


class Tool(ABC):
    """A capability the agent can invoke.

    Subclasses set ``name``, ``description`` and ``parameters`` (a JSON
    Schema object describing the arguments) and implement :meth:`execute`.
    """

    name: str
    description: str
    parameters: dict[str, Any]

    @abstractmethod
    async def execute(self, **arguments: Any) -> str:
        """Run the tool and return its output as a string."""

    def to_schema(self) -> dict[str, Any]:
        return {
            "name": self.name,
            "description": self.description,
            "parameters": self.parameters,
        }


class ToolRegistry:
    """Holds the tools available to an agent and dispatches calls to them."""

    def __init__(self, tools: list[Tool] | None = None) -> None:
        self._tools: dict[str, Tool] = {}
        for tool in tools or []:
            self.register(tool)

    def register(self, tool: Tool) -> None:
        self._tools[tool.name] = tool

    def get(self, name: str) -> Tool | None:
        return self._tools.get(name)

    def __len__(self) -> int:
        return len(self._tools)

    def schemas(self) -> list[dict[str, Any]]:
        return [tool.to_schema() for tool in self._tools.values()]

    async def execute(self, call: ToolCall) -> ToolResult:
        tool = self.get(call.name)
        if tool is None:
            return ToolResult(
                tool_call_id=call.id,
                content=f"Unknown tool {call.name!r}. Available: {sorted(self._tools)}",
                is_error=True,
            )
        try:
            output = await tool.execute(**call.arguments)
        except TypeError as exc:
            return ToolResult(
                tool_call_id=call.id,
                content=(
                    f"Invalid arguments for tool {call.name!r}: {exc}. "
                    f"Expected schema: {json.dumps(tool.parameters)}"
                ),
                is_error=True,
            )
        except Exception as exc:  # tools must never crash the agent loop
            return ToolResult(
                tool_call_id=call.id,
                content=f"{type(exc).__name__}: {exc}",
                is_error=True,
            )
        return ToolResult(tool_call_id=call.id, content=output)

"""Filesystem tools: read, write, edit and list files within a root directory."""

from __future__ import annotations

from pathlib import Path
from typing import Any

from codeagent.tools.base import Tool

MAX_READ_CHARS = 100_000


class _FilesystemTool(Tool):
    def __init__(self, root_dir: str | Path = ".", restrict_to_root: bool = True) -> None:
        self.root_dir = Path(root_dir).resolve()
        self.restrict_to_root = restrict_to_root

    def _resolve(self, path: str) -> Path:
        candidate = Path(path)
        if not candidate.is_absolute():
            candidate = self.root_dir / candidate
        resolved = candidate.resolve()
        if self.restrict_to_root and not (
            resolved == self.root_dir or self.root_dir in resolved.parents
        ):
            raise PermissionError(
                f"Path {path!r} escapes the workspace root {str(self.root_dir)!r}"
            )
        return resolved


class ReadFileTool(_FilesystemTool):
    name = "read_file"
    description = (
        "Read the contents of a file. Returns numbered lines. "
        "Use offset/limit to page through large files."
    )
    parameters = {
        "type": "object",
        "properties": {
            "path": {"type": "string", "description": "Path to the file, relative to the workspace root or absolute."},
            "offset": {"type": "integer", "description": "1-based line number to start reading from.", "minimum": 1},
            "limit": {"type": "integer", "description": "Maximum number of lines to read.", "minimum": 1},
        },
        "required": ["path"],
    }

    async def execute(self, path: str, offset: int = 1, limit: int | None = None, **_: Any) -> str:
        resolved = self._resolve(path)
        if not resolved.is_file():
            raise FileNotFoundError(f"No such file: {path!r}")
        text = resolved.read_text(errors="replace")
        if len(text) > MAX_READ_CHARS:
            text = text[:MAX_READ_CHARS] + "\n... [truncated]"
        lines = text.splitlines()
        start = max(offset - 1, 0)
        end = None if limit is None else start + limit
        selected = lines[start:end]
        if not selected:
            return "(empty)"
        width = len(str(start + len(selected)))
        return "\n".join(
            f"{i:>{width}}|{line}" for i, line in enumerate(selected, start=start + 1)
        )


class WriteFileTool(_FilesystemTool):
    name = "write_file"
    description = (
        "Write content to a file, creating it (and parent directories) if needed. "
        "Overwrites any existing content."
    )
    parameters = {
        "type": "object",
        "properties": {
            "path": {"type": "string", "description": "Path to the file to write."},
            "content": {"type": "string", "description": "Full content to write to the file."},
        },
        "required": ["path", "content"],
    }

    async def execute(self, path: str, content: str, **_: Any) -> str:
        resolved = self._resolve(path)
        resolved.parent.mkdir(parents=True, exist_ok=True)
        resolved.write_text(content)
        return f"Wrote {len(content)} characters to {path}"


class EditFileTool(_FilesystemTool):
    name = "edit_file"
    description = (
        "Replace an exact substring of a file with new content. "
        "The old_string must match exactly once unless replace_all is set."
    )
    parameters = {
        "type": "object",
        "properties": {
            "path": {"type": "string", "description": "Path to the file to edit."},
            "old_string": {"type": "string", "description": "Exact text to replace."},
            "new_string": {"type": "string", "description": "Replacement text."},
            "replace_all": {"type": "boolean", "description": "Replace every occurrence.", "default": False},
        },
        "required": ["path", "old_string", "new_string"],
    }

    async def execute(
        self,
        path: str,
        old_string: str,
        new_string: str,
        replace_all: bool = False,
        **_: Any,
    ) -> str:
        resolved = self._resolve(path)
        if not resolved.is_file():
            raise FileNotFoundError(f"No such file: {path!r}")
        text = resolved.read_text()
        occurrences = text.count(old_string)
        if occurrences == 0:
            raise ValueError(f"old_string not found in {path!r}")
        if occurrences > 1 and not replace_all:
            raise ValueError(
                f"old_string occurs {occurrences} times in {path!r}; "
                "provide more context or set replace_all=true"
            )
        updated = text.replace(old_string, new_string) if replace_all else text.replace(old_string, new_string, 1)
        resolved.write_text(updated)
        return f"Edited {path}: replaced {occurrences if replace_all else 1} occurrence(s)"


class ListDirTool(_FilesystemTool):
    name = "list_dir"
    description = "List files and directories at a path (non-recursive). Directories end with '/'."
    parameters = {
        "type": "object",
        "properties": {
            "path": {"type": "string", "description": "Directory path.", "default": "."},
        },
    }

    async def execute(self, path: str = ".", **_: Any) -> str:
        resolved = self._resolve(path)
        if not resolved.is_dir():
            raise NotADirectoryError(f"No such directory: {path!r}")
        entries = sorted(resolved.iterdir(), key=lambda p: (p.is_file(), p.name))
        if not entries:
            return "(empty directory)"
        return "\n".join(f"{p.name}/" if p.is_dir() else p.name for p in entries)

"""Codebase search tools: regex content search and glob file matching."""

from __future__ import annotations

import fnmatch
import re
from pathlib import Path
from typing import Any

from codeagent.tools.base import Tool

MAX_RESULTS = 200
_SKIP_DIRS = {".git", ".venv", "venv", "node_modules", "__pycache__", ".mypy_cache", ".pytest_cache", "dist", "build"}


def _iter_files(root: Path) -> list[Path]:
    files: list[Path] = []
    stack = [root]
    while stack:
        current = stack.pop()
        try:
            entries = sorted(current.iterdir(), key=lambda p: p.name)
        except OSError:
            continue
        for entry in entries:
            if entry.is_dir():
                if entry.name not in _SKIP_DIRS and not entry.is_symlink():
                    stack.append(entry)
            else:
                files.append(entry)
    return files


class GrepTool(Tool):
    name = "grep"
    description = (
        "Search file contents for a regex pattern. Returns matching lines as "
        "'path:line_number: content'. Skips common build/dependency directories."
    )
    parameters = {
        "type": "object",
        "properties": {
            "pattern": {"type": "string", "description": "Regular expression to search for."},
            "path": {"type": "string", "description": "File or directory to search in.", "default": "."},
            "include": {"type": "string", "description": "Glob filter for file names, e.g. '*.py'."},
        },
        "required": ["pattern"],
    }

    def __init__(self, root_dir: str | Path = ".") -> None:
        self.root_dir = Path(root_dir).resolve()

    async def execute(self, pattern: str, path: str = ".", include: str | None = None, **_: Any) -> str:
        target = (self.root_dir / path).resolve()
        if not target.exists():
            raise FileNotFoundError(f"No such path: {path!r}")
        regex = re.compile(pattern)

        files = [target] if target.is_file() else _iter_files(target)
        matches: list[str] = []
        for file in files:
            if include and not fnmatch.fnmatch(file.name, include):
                continue
            try:
                lines = file.read_text(errors="replace").splitlines()
            except OSError:
                continue
            for lineno, line in enumerate(lines, start=1):
                if regex.search(line):
                    matches.append(f"{file.relative_to(self.root_dir)}:{lineno}: {line.strip()}")
                    if len(matches) >= MAX_RESULTS:
                        return "\n".join(matches) + "\n... [truncated]"
        return "\n".join(matches) if matches else "(no matches)"


class GlobTool(Tool):
    name = "glob"
    description = (
        "Find files matching a glob pattern relative to the workspace root, "
        "e.g. '**/*.py'. Returns matching paths sorted by name."
    )
    parameters = {
        "type": "object",
        "properties": {
            "pattern": {"type": "string", "description": "Glob pattern, e.g. 'src/**/*.ts'."},
        },
        "required": ["pattern"],
    }

    def __init__(self, root_dir: str | Path = ".") -> None:
        self.root_dir = Path(root_dir).resolve()

    async def execute(self, pattern: str, **_: Any) -> str:
        matches = [
            p
            for p in self.root_dir.glob(pattern)
            if not any(part in _SKIP_DIRS for part in p.parts)
        ]
        matches.sort()
        if not matches:
            return "(no matches)"
        lines = [str(p.relative_to(self.root_dir)) for p in matches[:MAX_RESULTS]]
        result = "\n".join(lines)
        if len(matches) > MAX_RESULTS:
            result += f"\n... [{len(matches) - MAX_RESULTS} more]"
        return result

