import json
from pathlib import Path

import typer
from rich.console import Console
from rich.markdown import Markdown
from rich.panel import Panel
from rich.prompt import Prompt

from codeagent.core.agent import DEFAULT_SYSTEM_PROMPT, Agent, AgentEvent, MaxIterationsError
from codeagent.core.budget import Budget, BudgetExceededError
from codeagent.llm.registry import create_provider, list_providers
from codeagent.mcp import MCPManager, load_mcp_config
from codeagent.security.policy import ApprovalDecision, PermissionPolicy, RiskLevel
from codeagent.skills import SkillEvolver, SkillLibrary
from codeagent.tools import ToolRegistry, default_tools, web_tools
from codeagent.tools.ocr import ocr_tools
from codeagent.voice import (
    EMOTION_PROMPT_SUFFIX,
    EdgeTTSProvider,
    VoiceChatLoop,
    WhisperASRProvider,
    record_until_enter,
)

app = typer.Typer(name="codeagent", no_args_is_help=True)
console = Console()


def _make_event_handler(verbose: bool):
    def handler(event: AgentEvent) -> None:
        if event.type == "tool_call":
            console.print(f"tool: {event.data.name} {event.data.arguments}")
        elif event.type == "tool_result" and verbose:
            preview = event.data.content[:500]
            console.print(Panel(preview, title="result"))
        elif event.type == "error":
            console.print(f"error: {event.data}")
        elif event.type == "skill_evolved":
            console.print(f"skill evolved: {event.data.name}")
    return handler


def _make_approval_handler():
    def handler(call, risk: RiskLevel) -> ApprovalDecision:
        preview = json.dumps(call.arguments, ensure_ascii=False)
        console.print(preview[:300])
        choice = Prompt.ask("Allow?", choices=["y", "n", "a"], default="n")
        if choice == "y":
            return ApprovalDecision.APPROVE
        if choice == "a":
            return ApprovalDecision.ALWAYS_ALLOW
        return ApprovalDecision.DENY
    return handler


def _build_policy(auto_yes: bool) -> PermissionPolicy:
    if auto_yes:
        return PermissionPolicy.permissive()
    return PermissionPolicy(auto_approve_up_to=RiskLevel.READ_ONLY, handler=_make_approval_handler())


def _build_provider(provider, model, api_key, base_url):
    provider_kwargs = {"api_key": api_key, "base_url": base_url}
    provider_kwargs = {k: v for k, v in provider_kwargs.items() if v is not None}
    if model:
        provider_kwargs["model"] = model
    return create_provider(provider, **provider_kwargs)


def _build_agent(provider, model, api_key, base_url, root, max_iterations, verbose, auto_yes, budget_tokens, registry, skills=None, skill_evolver=None) -> Agent:
    budget = Budget(max_total_tokens=budget_tokens) if budget_tokens else None
    return Agent(
        provider=_build_provider(provider, model, api_key, base_url),
        tools=registry,
        max_iterations=max_iterations,
        permissions=_build_policy(auto_yes),
        budget=budget,
        skills=skills,
        skill_evolver=skill_evolver,
        on_event=_make_event_handler(verbose),
    )


_DEFAULT_SKILLS_DIR = Path("~/.codeagent/skills")


def _build_skills(skills_dir, evolve, provider, model, api_key, base_url):
    directory = skills_dir or (_DEFAULT_SKILLS_DIR if _DEFAULT_SKILLS_DIR.expanduser().is_dir() else None)
    if directory is None:
        return None, None
    library = SkillLibrary.load(directory)
    evolver = None
    if evolve:
        evolver = SkillEvolver(
            provider=_build_provider(provider, model, api_key, base_url),
            library=library,
            directory=directory,
        )
    return library, evolver


@app.command()
def run(task, provider="anthropic", model=None, api_key=None, base_url=None, root=Path.cwd(), max_iterations=50, budget=None, mcp_config=None, web=False, ocr=False, skills_dir=None, evolve=False, yes=False, verbose=False) -> None:
    async def _run() -> None:
        registry = default_tools(root)
        if web:
            for tool in web_tools():
                registry.register(tool)
        if ocr:
            for tool in ocr_tools():
                registry.register(tool)
        skills, evolver = _build_skills(skills_dir, evolve, provider, model, api_key, base_url)
        mcp_configs = load_mcp_config(mcp_config) if mcp_config else []
        async with MCPManager(mcp_configs) as mcp:
            for tool in mcp.tools():
                registry.register(tool)
            agent = _build_agent(provider, model, api_key, base_url, root, max_iterations, verbose, yes, budget, registry, skills=skills, skill_evolver=evolver)
            try:
                answer = await agent.run(task)
            except (MaxIterationsError, BudgetExceededError) as exc:
                console.print(str(exc))
                raise typer.Exit(code=1)
        console.print(Markdown(answer))
    asyncio.run(_run())


@app.command()
def chat(provider="anthropic", model=None, api_key=None, base_url=None, root=Path.cwd(), max_iterations=50, budget=None, mcp_config=None, web=False, ocr=False, skills_dir=None, evolve=False, yes=False, verbose=False, emotion=False, voice=False, voice_name=None, mic=False, mic_model="base", memory=False) -> None:
    async def _chat() -> None:
        registry = default_tools(root)
        if web:
            for tool in web_tools():
                registry.register(tool)
        if ocr:
            for tool in ocr_tools():
                registry.register(tool)
        skills, evolver = _build_skills(skills_dir, evolve, provider, model, api_key, base_url)
        memory_store = None
        if memory:
            from codeagent.memory import LocalMemoryStore, memory_tools
            memory_store = LocalMemoryStore("~/.codeagent/memory.json")
            for tool in memory_tools(memory_store):
                registry.register(tool)
        mcp_configs = load_mcp_config(mcp_config) if mcp_config else []
        async with MCPManager(mcp_configs) as mcp:
            for tool in mcp.tools():
                registry.register(tool)
            agent = _build_agent(provider, model, api_key, base_url, root, max_iterations, verbose, yes, budget, registry, skills=skills, skill_evolver=evolver)
            agent.memory = memory_store
            if emotion or voice:
                agent.system_prompt = DEFAULT_SYSTEM_PROMPT + EMOTION_PROMPT_SUFFIX
            tts = None
            if voice or mic:
                if voice_name:
                    tts = EdgeTTSProvider(voice=voice_name, emotion_voices=False)
                else:
                    tts = EdgeTTSProvider()
            asr = WhisperASRProvider(model_size=mic_model) if mic else None
            loop = VoiceChatLoop(agent, tts=tts)
            while True:
                try:
                    if mic:
                        audio = await record_until_enter()
                        user_input = await asr.transcribe(audio)
                        if not user_input.strip():
                            continue
                    else:
                        user_input = console.input("you> ")
                except (EOFError, KeyboardInterrupt):
                    return
                except RuntimeError:
                    return
                if not user_input.strip():
                    continue
                if user_input.strip() == "reset":
                    agent.reset()
                    continue
                try:
                    turn = await loop.turn(user_input)
                except (MaxIterationsError, BudgetExceededError):
                    continue
                if turn is None:
                    return
                console.print(Markdown(turn.reply_text))
    asyncio.run(_chat())


if __name__ == "__main__":
    app()

