"""External agent platform adapters (HiveWard's "harness employees").

When a worker is stuck, confused, or fails outright, it can hand the task to
another agent platform installed on this computer — Claude Code, Codex,
Gemini CLI, cursor-agent, opencode — via its CLI, in headless mode.
"""

from __future__ import annotations

import asyncio
import shutil
from dataclasses import dataclass, field
from pathlib import Path


@dataclass
class HarnessResult:
    harness: str
    ok: bool
    output: str
    exit_code: int | None = None


@dataclass(frozen=True)
class CliHarness:
    """A headless CLI agent platform. ``argv`` contains a {prompt} slot."""

    name: str
    argv: tuple[str, ...]
    timeout: float = 300.0
    description: str = ""

    @property
    def executable(self) -> str:
        return self.argv[0]

    def available(self) -> bool:
        return shutil.which(self.executable) is not None

    async def run(self, prompt: str, cwd: str | Path | None = None) -> HarnessResult:
        if not self.available():
            return HarnessResult(self.name, False, f"{self.executable} 未安装")
        argv = [part.replace("{prompt}", prompt) for part in self.argv]
        try:
            proc = await asyncio.create_subprocess_exec(
                *argv,
                cwd=str(cwd) if cwd else None,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.PIPE,
            )
            stdout, stderr = await asyncio.wait_for(proc.communicate(), self.timeout)
        except asyncio.TimeoutError:
            return HarnessResult(self.name, False, f"超时（{self.timeout}秒）")
        except OSError as exc:
            return HarnessResult(self.name, False, f"启动失败: {exc}")
        out = stdout.decode(errors="replace").strip()
        err = stderr.decode(errors="replace").strip()
        if proc.returncode != 0:
            return HarnessResult(self.name, False, err or out or f"exit {proc.returncode}", proc.returncode)
        return HarnessResult(self.name, True, out or "(无输出)", proc.returncode)


HARNESS_PRESETS: dict[str, CliHarness] = {
    "claude-code": CliHarness(
        "claude-code",
        ("claude", "-p", "{prompt}", "--output-format", "text"),
        description="Claude Code（Anthropic 官方 CLI）",
    ),
    "codex": CliHarness(
        "codex",
        ("codex", "exec", "{prompt}"),
        description="OpenAI Codex CLI",
    ),
    "gemini": CliHarness(
        "gemini",
        ("gemini", "-p", "{prompt}"),
        description="Google Gemini CLI",
    ),
    "cursor-agent": CliHarness(
        "cursor-agent",
        ("cursor-agent", "-p", "{prompt}", "--output-format", "text"),
        description="Cursor CLI agent",
    ),
    "opencode": CliHarness(
        "opencode",
        ("opencode", "run", "{prompt}"),
        description="OpenCode CLI",
    ),
}


def discover_harnesses(extra: list[CliHarness] | None = None) -> list[CliHarness]:
    """Return the agent platforms actually installed on this machine."""
    candidates = list(HARNESS_PRESETS.values()) + list(extra or [])
    return [h for h in candidates if h.available()]

"""ask_external_agent: a tool letting a stuck worker call another agent platform."""

from __future__ import annotations

from pathlib import Path
from typing import Any

from codeagent.harness.adapters import CliHarness, HarnessResult, discover_harnesses
from codeagent.security.policy import RiskLevel
from codeagent.tools.base import Tool


class AskHarnessTool(Tool):
    name = "ask_external_agent"
    description = (
        "当你遇到困难、不理解需求、或凭自身能力无法完成时，呼叫本机安装的"
        "其他 agent 平台（如 Claude Code / Codex / Gemini CLI）帮忙。"
        "把任务背景、你已尝试的方案、卡在哪里写清楚，它会直接在工作目录里操作。"
    )
    parameters: dict[str, Any] = {
        "type": "object",
        "properties": {
            "prompt": {
                "type": "string",
                "description": "完整的求助描述：任务背景 + 已尝试方案 + 卡点。",
            },
            "harness": {
                "type": "string",
                "description": "指定平台名（如 claude-code/codex/gemini）；不填则自动选第一个可用的。",
            },
        },
        "required": ["prompt"],
    }
    risk_level = RiskLevel.EXECUTE  # external agent may modify the workspace

    def __init__(
        self,
        harnesses: list[CliHarness] | None = None,
        cwd: str | Path | None = None,
    ) -> None:
        self.harnesses = harnesses if harnesses is not None else discover_harnesses()
        self.cwd = Path(cwd) if cwd else None

    async def execute(self, prompt: str, harness: str | None = None) -> str:
        if not self.harnesses:
            return (
                "本机未发现可用的外部 agent 平台（claude/codex/gemini/"
                "cursor-agent/opencode 均未安装）。请换个思路自己解决。"
            )
        chosen = None
        if harness:
            chosen = next((h for h in self.harnesses if h.name == harness), None)
            if chosen is None:
                names = ", ".join(h.name for h in self.harnesses)
                return f"平台 {harness!r} 不可用；本机可用：{names}"
