"""JS bridge for the desktop UI.

A ``DesktopAPI`` instance is exposed to the webview's JavaScript as
``pywebview.api.*``. Python pushes live updates back via
``window.evaluate_js``. No web server involved.

UI preferences (provider/model/key) persist to ``~/.codeagent/desktop.json``;
personalization reuses the host-wide ``Settings`` store.
"""

from __future__ import annotations

import asyncio
import json
import threading
from dataclasses import asdict, dataclass
from pathlib import Path
from typing import Any

from codeagent.core.agent import Agent
from codeagent.core.budget import Budget
from codeagent.core.types import AgentEvent
from codeagent.llm.aggregate import parse_provider_spec
from codeagent.llm.registry import list_providers
from codeagent.log import get_logger, setup_logging
from codeagent.releases import changelog_text, latest
from codeagent.settings import Settings
from codeagent.tools import default_tools

log = get_logger("desktop")

DESKTOP_CONFIG_PATH = Path("~/.codeagent/desktop.json")


@dataclass
class DesktopConfig:
    """Model connection chosen in the UI."""

    provider: str = "ollama"
    model: str = ""
    api_key: str = ""
    base_url: str = ""
    strategy: str = "fallback"
    auto_yes: bool = False

    @classmethod
    def load(cls, path: Path = DESKTOP_CONFIG_PATH) -> "DesktopConfig":
        path = Path(path).expanduser()
        if not path.is_file():
            return cls()
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except (json.JSONDecodeError, OSError):
            return cls()
        known = {f for f in cls.__dataclass_fields__}
        return cls(**{k: v for k, v in data.items() if k in known})

    def save(self, path: Path = DESKTOP_CONFIG_PATH) -> None:
        path = Path(path).expanduser()
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(asdict(self), ensure_ascii=False, indent=2),
                        encoding="utf-8")


class DesktopAPI:
    """Object exposed to JavaScript. All methods are callable from JS."""

    def __init__(self, root: Path | None = None) -> None:
        self.root = Path.cwd() if root is None else Path(root)
        self.config = DesktopConfig.load()
        self.settings = Settings.load()
        self._window: Any = None  # set by run_desktop once the window exists
        self._agent: Agent | None = None
        self._lock = threading.Lock()
        self._busy = False
        setup_logging()

    # ------------------------------------------------------------------
    # push channel
    # ------------------------------------------------------------------

    def _push(self, kind: str, **data: Any) -> None:
        if self._window is None:
            return
        payload = json.dumps({"kind": kind, **data}, ensure_ascii=False)
        try:
            self._window.evaluate_js(f"window._onEvent({payload})")
        except Exception:  # noqa: BLE001 — UI push must never crash the agent
            log.exception("push failed")

    def _on_event(self, event: AgentEvent) -> None:
        if event.type == "text":
            self._push("text", text=str(event.data))
        elif event.type == "tool_call":
            call = event.data
            self._push("tool", name=call.name)
        elif event.type == "approval":
            self._push("status", text="等待审批（请在终端确认）…")

    # ------------------------------------------------------------------
    # JS-facing: state & settings
    # ------------------------------------------------------------------

    def get_state(self) -> dict[str, Any]:
        rel = latest()
        return {
            "version": rel.version,
            "date": rel.date,
            "highlights": list(rel.highlights),
            "providers": list_providers(),
            "config": asdict(self.config),
            "settings": asdict(self.settings),
            "root": str(self.root),
        }

    def get_changelog(self) -> str:
        return changelog_text()

    def save_config(self, data: dict[str, Any]) -> dict[str, Any]:
        for key in ("provider", "model", "api_key", "base_url", "strategy"):
            if key in data:
                setattr(self.config, key, str(data[key]))
        if "auto_yes" in data:
            self.config.auto_yes = bool(data["auto_yes"])
        self.config.save()
        self._agent = None  # rebuild on next message
        log.info("desktop config saved: provider=%s model=%s",
                 self.config.provider, self.config.model)
        return asdict(self.config)

    def save_settings(self, data: dict[str, Any]) -> dict[str, Any]:
        for key in ("nickname", "language", "instructions", "context"):
            if key in data:
                setattr(self.settings, key, str(data[key]))
        self.settings.save()
        if self._agent is not None:
            self._agent.settings = self.settings
        return asdict(self.settings)

    # ------------------------------------------------------------------
    # JS-facing: chat
    # ------------------------------------------------------------------

    def _build_agent(self) -> Agent:
        kwargs: dict[str, Any] = {}
        if self.config.model:
            kwargs["model"] = self.config.model
        if self.config.api_key:
            kwargs["api_key"] = self.config.api_key
        if self.config.base_url:
            kwargs["base_url"] = self.config.base_url
        provider = parse_provider_spec(
            self.config.provider, strategy=self.config.strategy, **kwargs
        )
        from codeagent.security.policy import PermissionPolicy

        policy = (
            PermissionPolicy.permissive()
            if self.config.auto_yes
            else PermissionPolicy.interactive()
        )
        return Agent(
            provider=provider,
            tools=default_tools(self.root),
            permissions=policy,
            budget=Budget(max_total_tokens=500_000),
            settings=self.settings,
            on_event=self._on_event,
        )

    def send(self, text: str) -> bool:
        """Send a chat message; replies stream back via push events."""
        text = (text or "").strip()
        if not text:
            return False
        with self._lock:
            if self._busy:
                return False
            self._busy = True
        threading.Thread(target=self._run_chat, args=(text,), daemon=True).start()
        return True

    def _run_chat(self, text: str) -> None:
        try:
            if self._agent is None:
                self._push("status", text="正在连接模型…")
                self._agent = self._build_agent()
            answer = asyncio.run(self._agent.run(text))
            self._push("done", text=answer)
        except Exception as exc:  # noqa: BLE001 — surface to the UI
            log.exception("chat failed")
            self._push("error", text=str(exc))
        finally:
            with self._lock:
                self._busy = False

    def reset(self) -> bool:
        if self._agent is not None:
            self._agent.reset()
        self._agent = None
        return True

