           background: var(--panel); border-bottom: 1px solid var(--border); }
  header .logo { font-weight: 700; font-size: 15px; }
  header .ver { color: var(--dim); font-size: 12px; }
  header select, header input { background: var(--bg); color: var(--text);
    border: 1px solid var(--border); border-radius: 6px; padding: 5px 8px; font-size: 12px; }
  header .spacer { flex: 1; }
  header button { background: transparent; color: var(--dim); border: 1px solid var(--border);
    border-radius: 6px; padding: 5px 10px; font-size: 12px; cursor: pointer; }
  header button:hover { color: var(--text); border-color: var(--accent); }

  #chat { flex: 1; overflow-y: auto; padding: 18px 16px; display: flex;
          flex-direction: column; gap: 12px; }
  .msg { max-width: 78%; padding: 10px 14px; border-radius: 12px;
         font-size: 14px; line-height: 1.65; white-space: pre-wrap;
         word-break: break-word; }
  .msg.user { align-self: flex-end; background: var(--user); color: #fff;
              border-bottom-right-radius: 4px; }
  .msg.bot { align-self: flex-start; background: var(--panel);
             border: 1px solid var(--border); border-bottom-left-radius: 4px; }
  .msg pre { background: #0a0c10; border-radius: 8px; padding: 10px;
             overflow-x: auto; margin: 8px 0; font-size: 12.5px; }
  .msg code { font-family: "SF Mono", Menlo, Consolas, monospace;
              background: #0a0c10; border-radius: 4px; padding: 1px 5px; }
  .msg pre code { background: none; padding: 0; }
  .chip { align-self: flex-start; font-size: 12px; color: var(--dim);
          border: 1px dashed var(--border); border-radius: 999px;
          padding: 3px 12px; }
  .chip.error { color: #ff7b72; border-color: #ff7b72; }
  .chip.status { color: var(--accent); }

  #composer { display: flex; gap: 10px; padding: 12px 16px;
              background: var(--panel); border-top: 1px solid var(--border); }
  #input { flex: 1; resize: none; background: var(--bg); color: var(--text);
           border: 1px solid var(--border); border-radius: 10px;
           padding: 10px 12px; font-size: 14px; font-family: inherit; }
  #input:focus { outline: none; border-color: var(--accent); }
  #send { background: var(--accent); color: #fff; border: none;
          border-radius: 10px; padding: 0 22px; font-size: 14px; cursor: pointer; }
  #send:disabled { opacity: .45; cursor: default; }

  .modal-mask { position: fixed; inset: 0; background: rgba(0,0,0,.55);
                display: none; align-items: center; justify-content: center; }
  .modal { width: 460px; max-height: 80vh; overflow-y: auto; background: var(--panel);
           border: 1px solid var(--border); border-radius: 14px; padding: 20px; }
  .modal h2 { font-size: 15px; margin-bottom: 14px; }
  .modal label { display: block; font-size: 12px; color: var(--dim); margin: 10px 0 4px; }
  .modal input, .modal textarea, .modal select { width: 100%; background: var(--bg);
    color: var(--text); border: 1px solid var(--border); border-radius: 8px;
    padding: 8px 10px; font-size: 13px; font-family: inherit; }
  .modal textarea { resize: vertical; min-height: 60px; }
  .modal .row { display: flex; gap: 10px; margin-top: 16px; justify-content: flex-end; }
  .modal button { border: none; border-radius: 8px; padding: 8px 18px;
                  font-size: 13px; cursor: pointer; }
  .modal .primary { background: var(--accent); color: #fff; }
  .modal .ghost { background: transparent; color: var(--dim);
                  border: 1px solid var(--border); }
  .modal .md { font-size: 13px; line-height: 1.7; color: var(--text); }
  .modal .md h2 { margin-top: 14px; color: var(--accent); }
  .checkline { display: flex; align-items: center; gap: 8px; margin-top: 12px;
               font-size: 13px; color: var(--text); }
  .checkline input { width: auto; }
</style>
</head>
<body>
<header>
  <span class="logo">codeagent</span>
  <span class="ver" id="ver"></span>
  <select id="provider"></select>
  <input id="model" placeholder="模型（可空，用默认）" size="18">
  <span class="spacer"></span>
  <button onclick="openSettings()">设置</button>
  <button onclick="openAbout()">版本</button>
  <button onclick="resetChat()">新对话</button>
</header>

<div id="chat"></div>

<div id="composer">
  <textarea id="input" rows="2" placeholder="输入消息，Enter 发送，Shift+Enter 换行"></textarea>
  <button id="send" onclick="send()">发送</button>
</div>

<div class="modal-mask" id="settingsMask">
  <div class="modal">
    <h2>设置</h2>
    <label>API Key（留空则用环境变量）</label>
    <input id="cfg_key" type="password" placeholder="sk-...">
    <label>Base URL（自建中转 / 兼容端点）</label>
    <input id="cfg_base" placeholder="http://localhost:3000/v1">
    <label>聚合策略（provider 用逗号串联多个时生效）</label>
    <select id="cfg_strategy">
      <option value="fallback">fallback（故障转移）</option>
      <option value="round-robin">round-robin（轮询）</option>
    </select>
    <div class="checkline">
      <input type="checkbox" id="cfg_yes">
      <span>自动批准所有工具调用（含写文件/执行命令，慎用）</span>
    </div>
    <h2 style="margin-top:18px">个性化（本机所有对话生效）</h2>
    <label>怎么称呼你</label><input id="set_nick">
    <label>首选语言</label><input id="set_lang" placeholder="中文">
    <label>额外说明</label><textarea id="set_inst"></textarea>
    <label>用户与主机上下文</label><textarea id="set_ctx"></textarea>
    <div class="row">
      <button class="ghost" onclick="closeModal('settingsMask')">取消</button>
      <button class="primary" onclick="saveSettings()">保存</button>
    </div>
  </div>
</div>

<div class="modal-mask" id="aboutMask">
  <div class="modal">
    <h2 id="aboutTitle"></h2>
    <div class="md" id="aboutBody"></div>
    <div class="row">
      <button class="primary" onclick="closeModal('aboutMask')">关闭</button>
    </div>
  </div>
</div>

<script>
const chat = document.getElementById('chat');
const input = document.getElementById('input');
const sendBtn = document.getElementById('send');
let curBot = null;

function esc(s) {
  return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}
function render(s) {
  let h = esc(s);
  h = h.replace(/```(\w*)\n?([\s\S]*?)```/g, (_, l, c) => '<pre><code>' + c + '</code></pre>');
  h = h.replace(/`([^`\n]+)`/g, '<code>$1</code>');
  return h;
}
function addMsg(cls, text) {
  const div = document.createElement('div');
  div.className = 'msg ' + cls;
  div.innerHTML = render(text);
  chat.appendChild(div);
  chat.scrollTop = chat.scrollHeight;
  return div;
}
function addChip(cls, text) {
  const div = document.createElement('div');
  div.className = 'chip ' + cls;
  div.textContent = text;
  chat.appendChild(div);
  chat.scrollTop = chat.scrollHeight;
}

window._onEvent = function(ev) {
  if (ev.kind === 'text') {
    if (!curBot) curBot = addMsg('bot', '');
    curBot.innerHTML = render(ev.text);
    chat.scrollTop = chat.scrollHeight;
  } else if (ev.kind === 'tool') {
    addChip('', '🔧 ' + ev.name);
  } else if (ev.kind === 'status') {
    addChip('status', ev.text);
  } else if (ev.kind === 'done') {
    curBot = null;
    sendBtn.disabled = false;
  } else if (ev.kind === 'error') {
    addChip('error', '出错了：' + ev.text);
    curBot = null;
    sendBtn.disabled = false;
  }
};

function send() {
  const text = input.value.trim();
  if (!text) return;
  addMsg('user', text);
  input.value = '';
  sendBtn.disabled = true;
  curBot = null;
  pywebview.api.send(text).then(ok => {
    if (!ok) { addChip('error', '上一条还在处理中'); sendBtn.disabled = false; }
  });
}

input.addEventListener('keydown', e => {
  if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); send(); }
});

function openModal(id) { document.getElementById(id).style.display = 'flex'; }
function closeModal(id) { document.getElementById(id).style.display = 'none'; }

function openSettings() {
  pywebview.api.get_state().then(st => {
    document.getElementById('cfg_key').value = st.config.api_key;
    document.getElementById('cfg_base').value = st.config.base_url;
    document.getElementById('cfg_strategy').value = st.config.strategy;
    document.getElementById('cfg_yes').checked = st.config.auto_yes;
    document.getElementById('set_nick').value = st.settings.nickname;
    document.getElementById('set_lang').value = st.settings.language;
    document.getElementById('set_inst').value = st.settings.instructions;
    document.getElementById('set_ctx').value = st.settings.context;
    openModal('settingsMask');
  });
}

function saveSettings() {
  const cfg = {
    provider: document.getElementById('provider').value,
    model: document.getElementById('model').value,
    api_key: document.getElementById('cfg_key').value,
    base_url: document.getElementById('cfg_base').value,
    strategy: document.getElementById('cfg_strategy').value,
    auto_yes: document.getElementById('cfg_yes').checked,
  };
  const ps = {
    nickname: document.getElementById('set_nick').value,
    language: document.getElementById('set_lang').value,
    instructions: document.getElementById('set_inst').value,
    context: document.getElementById('set_ctx').value,
  };
  Promise.all([
    pywebview.api.save_config(cfg),
    pywebview.api.save_settings(ps),
  ]).then(() => { closeModal('settingsMask'); addChip('status', '设置已保存'); });
}

function openAbout() {
  Promise.all([pywebview.api.get_state(), pywebview.api.get_changelog()])
    .then(([st, log]) => {
      document.getElementById('aboutTitle').textContent =
        'codeagent v' + st.version + '（' + st.date + '）';
      document.getElementById('aboutBody').innerHTML =
        render(log).replace(/\n/g, '<br>');
      openModal('aboutMask');
    });
}

function resetChat() {
  pywebview.api.reset().then(() => {
    chat.innerHTML = '';
    addChip('status', '新对话已开始');
  });
}

// provider/model 选择即时保存
function bindHeader() {
  pywebview.api.get_state().then(st => {
    document.getElementById('ver').textContent = 'v' + st.version;
    const sel = document.getElementById('provider');
    st.providers.forEach(p => {
      const o = document.createElement('option');
      o.value = p; o.textContent = p;
      sel.appendChild(o);
    });
    sel.value = st.config.provider;
    document.getElementById('model').value = st.config.model;
    const persist = () => pywebview.api.save_config({
      provider: sel.value, model: document.getElementById('model').value,
    });
    sel.onchange = persist;
    document.getElementById('model').onchange = persist;
  });
}
bindHeader();
</script>
</body>
</html>
"""

