def build_policy(levels: dict[str, str], confirmer: Confirmer | None) -> PermissionPolicy:
    """Levels → PermissionPolicy (fail closed for unknown tools)."""
    allow: set[str] = set()
    deny: set[str] = set()
    confirm_tools: set[str] = set()
    for cap in CAPABILITIES:
        level = levels.get(cap["id"], "confirm")
        tools = set(cap["tools"])
        if level == "full":
            allow |= tools
        elif level == "off":
            deny |= tools
        elif level == "readonly":
            allow |= set(cap["readonly_tools"])
            deny |= tools - set(cap["readonly_tools"])
        else:  # confirm
            confirm_tools |= tools

    def handler(call: ToolCall, risk: RiskLevel):
        if call.name in confirm_tools and confirmer is not None:
            return confirmer.ask(call, risk)
        return ApprovalDecision.DENY

    return PermissionPolicy(
        auto_approve_up_to=RiskLevel.DESTRUCTIVE,  # per-tool sets decide
        handler=handler,
        always_allow=allow,
        always_deny=deny,
    )

