  try{
    const h=new URL(baseUrl).hostname.toLowerCase();
    const t=[[/openai\.com/,'OpenAI'],[/deepseek/,'DeepSeek'],[/moonshot/,'Kimi（Moonshot）'],
      [/minimax/,'MiniMax'],[/bigmodel|zhipu/,'智谱 GLM'],[/dashscope|aliyun/,'通义千问'],
