      [/^(localhost|127\.|192\.168\.|10\.|172\.)/,'本地/局域网']];
    for(const [re,name] of t)if(re.test(h))return name;
    const s=h.split('.').slice(-2,-1)[0]||'自定义';
    return s.charAt(0).toUpperCase()+s.slice(1);
  }catch(e){return '自定义';}
