function pullModel(){
  const name=$('pull_name').value.trim(); if(!name)return;
  pywebview.api.pull_model(name).then(r=>{
    if(!r.ok){toast(r.error);return;}
    toast('开始部署 '+name+'（'+r.endpoint+'），完成后可在此启动');
    $('pull_name').value='';
