      '<button class="iconbtn danger">🗑</button></div>';
    const [testBtn,useBtn,delBtn]=div.querySelectorAll('button');
    const result=div.querySelector('.t-result');
    testBtn.onclick=()=>{
      result.textContent='测试中…';
