import asyncio
import json
import threading
import time
import uuid
from dataclasses import asdict, dataclass, field
from pathlib import Path
from typing import Any, Callable

from codeagent.desktop.activity import log_activity
from codeagent.desktop.permissions import append_audit

WORKFLOWS_PATH = Path("~/.codeagent/workflows.json").expanduser()
TRIGGERS = ("manual", "cron", "event", "feishu")
CONTINUOUS_DELAY_S = 5.0

@dataclass
class WorkflowStep:
    name: str
    tool: str = ""

@dataclass
class Workflow:
    name: str
    desc: str = ""
    trigger: str = "manual"
    continuous: bool = False
    steps: list[WorkflowStep] = field(default_factory=list)
    status: str = "idle"
    runs: int = 0
    last_run: str = "-"
    id: str = field(default_factory=lambda: "wf-" + uuid.uuid4().hex[:6])

@dataclass
class WorkflowStore:
    workflows: list[Workflow] = field(default_factory=list)

    @classmethod
    def load(cls, path: Path | None = None) -> "WorkflowStore":
        path = path or WORKFLOWS_PATH
        if not path.exists():
            return cls()
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except (json.JSONDecodeError, OSError):
            return cls()
        return cls(workflows=[Workflow(**{**w, "steps": [WorkflowStep(**s) for s in w.get("steps", [])]}) for w in data.get("workflows", [])])

    def save(self, path: Path | None = None) -> None:
        path = path or WORKFLOWS_PATH
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps({"workflows": [{**asdict(w), "steps": [asdict(s) for s in w.steps]} for w in self.workflows]}, ensure_ascii=False, indent=2), encoding="utf-8")

    def get(self, wf_id: str) -> Workflow | None:
        return next((w for w in self.workflows if w.id == wf_id), None)

class WorkflowRunner:
    def __init__(self, store, run_step, on_change=None):
        self.store = store
        self._run_step = run_step
        self._on_change = on_change or (lambda w: None)
        self._threads = {}

    def _changed(self, wf):
        self.store.save()
        self._on_change(wf)

    def start(self, wf_id):
        wf = self.store.get(wf_id)
        if wf is None or wf.status == "running":
            return False
        wf.status = "running"
        wf.runs += 1
        wf.last_run = time.strftime("%Y-%m-%d %H:%M:%S")
        log_activity("workflow", f"start {wf.name} #{wf.runs}")
        append_audit("workflow", f"run {wf.name}", "allowed")
        self._changed(wf)
        t = threading.Thread(target=self._loop, args=(wf_id,), daemon=True)
        self._threads[wf_id] = t
        t.start()
        return True

    def _loop(self, wf_id):
        while True:
            wf = self.store.get(wf_id)
            if wf is None or wf.status != "running":
                return
            try:
                context = ""
                for step in wf.steps:
                    context = self._run_step(step, context)
                log_activity("workflow", f"done {wf.name}")
            except Exception as exc:
                log_activity("workflow", f"fail {wf.name}: {str(exc)[:120]}")
                wf.status = "idle"
                self._changed(wf)
                return
            wf = self.store.get(wf_id)
            if wf is None:
                return
            if wf.continuous and wf.status == "running":
                time.sleep(CONTINUOUS_DELAY_S)
                continue
            wf.status = "idle"
            self._changed(wf)
            return

    def pause(self, wf_id):
        wf = self.store.get(wf_id)
        if wf is None:
            return False
        wf.status = "idle" if wf.status == "paused" else "paused"
        log_activity("workflow", f"pause/resume {wf.name}")
        self._changed(wf)
        return True

    def set_continuous(self, wf_id, on):
        wf = self.store.get(wf_id)
        if wf is None:
            return False
        wf.continuous = on
        append_audit("user", f"continuous {wf.name}={on}", "confirmed" if on else "allowed")
        self._changed(wf)
        return True

import json
import threading
import time
import uuid
from dataclasses import asdict, dataclass, field
from pathlib import Path
from typing import Any, Callable

from codeagent.desktop.activity import log_activity

CRON_PATH = Path("~/.codeagent/cron.json").expanduser()
PRESETS = [{"label": "30min", "cron": "*/30 * * * *"}, {"label": "0800", "cron": "0 8 * * *"}]

def _parse_field(spec, lo, hi):
    out = set()
    for part in spec.split(","):
        part = part.strip()
        if not part:
            return None
        step = 1
        if "/" in part:
            part, s = part.split("/", 1)
            if not s.isdigit() or int(s) < 1:
                return None
            step = int(s)
        if part == "*":
            start, end = lo, hi
        elif "-" in part:
            a, b = part.split("-", 1)
            if not (a.isdigit() and b.isdigit()):
                return None
            start, end = int(a), int(b)
        elif part.isdigit():
            start = end = int(part)
        else:
            return None
        if start < lo or end > hi or start > end:
            return None
        out.update(range(start, end + 1, step))
    return out

def cron_matches(expr, tm):
    fields = expr.split()
    if len(fields) != 5:
        return False
    minute = _parse_field(fields[0], 0, 59)
    hour = _parse_field(fields[1], 0, 23)
    day = _parse_field(fields[2], 1, 31)
    month = _parse_field(fields[3], 1, 12)
    weekday = _parse_field(fields[4], 0, 7)
    if None in (minute, hour, day, month, weekday):
        return False
    wd = (tm.tm_wday + 1) % 7
    return tm.tm_min in minute and tm.tm_hour in hour and tm.tm_mday in day and tm.tm_mon in month and (wd in weekday or (wd == 0 and 7 in weekday))

def next_run_hint(expr):
    now = time.time()
    t = now - now % 60 + 60
    for _ in range(7 * 24 * 60):
        tm = time.localtime(t)
        if cron_matches(expr, tm):
            return time.strftime("%m-%d %H:%M", tm)
        t += 60
    return "pending"

@dataclass
class CronJob:
    name: str
    schedule: str
    action: str
    target: str = "workflow"
    enabled: bool = True
    last_run: str = "-"
    next_run: str = "pending"
    last_result: str = "-"
    id: str = field(default_factory=lambda: uuid.uuid4().hex[:8])

@dataclass
class CronStore:
    jobs: list[CronJob] = field(default_factory=list)

    @classmethod
    def load(cls, path=None):
        path = path or CRON_PATH
        if not path.exists():
            return cls()
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except (json.JSONDecodeError, OSError):
            return cls()
        return cls(jobs=[CronJob(**j) for j in data.get("jobs", [])])

    def save(self, path=None):
        path = path or CRON_PATH
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps({"jobs": [asdict(j) for j in self.jobs]}, ensure_ascii=False, indent=2), encoding="utf-8")

class CronScheduler:
    def __init__(self, store, run_action, on_tick=None, evolution_enabled=None, evolution_cron=None, run_evolution=None):
        self.store = store
        self._run_action = run_action
        self._on_tick = on_tick or (lambda: None)
        self._evo_enabled = evolution_enabled or (lambda: False)
        self._evo_cron = evolution_cron or (lambda: "0 2 * * *")
        self._run_evolution = run_evolution
        self._stop = threading.Event()
        self._thread = None
        self._last_minute = ""

    def start(self):
        if self._thread is not None:
            return
        self._thread = threading.Thread(target=self._loop, daemon=True)
        self._thread.start()

    def stop(self):
        self._stop.set()

    def _loop(self):
        while not self._stop.wait(30):
            try:
                self.tick()
            except Exception:
                continue

    def tick(self, now=None):
        tm = time.localtime(now or time.time())
        minute_key = time.strftime("%Y-%m-%d %H:%M", tm)
        if minute_key == self._last_minute:
            return []
        fired = []
        for job in self.store.jobs:
            if not job.enabled or not cron_matches(job.schedule, tm):
                continue
            job.last_run = time.strftime("%Y-%m-%d %H:%M:%S", tm)
            try:
                ok = bool(self._run_action(job))
            except Exception:
                ok = False
            job.last_result = "success" if ok else "failed"
            job.next_run = next_run_hint(job.schedule)
            log_activity("cron", f"job {job.name} ok={ok}")
            fired.append(job.id)
        if self._evo_enabled() and self._run_evolution is not None and cron_matches(self._evo_cron(), tm):
            log_activity("cron", "evolution job fired")
            try:
                self._run_evolution()
            except Exception:
                pass
            fired.append("__evolution__")
        if fired:
            self.store.save()
        self._last_minute = minute_key
        self._on_tick()
        return fired

import json
import time
import uuid
from dataclasses import asdict, dataclass, field
from pathlib import Path
from typing import Any

from codeagent.desktop.activity import log_activity
from codeagent.desktop.permissions import append_audit

EVOLUTION_PATH = Path("~/.codeagent/evolution.json").expanduser()
PHASES = ("review", "attribute", "route", "memory", "teach")
PATCH_POOL = [{"title": "t", "content": "c", "source": "s", "level": "L0"}]
SKILL_POOL = [{"name": "n", "desc": "d", "reason": "r"}]

@dataclass
class BehaviorPatch:
    title: str
    content: str
    source: str
    level: str = "L0"
    status: str = "pending"
    date: str = ""
    id: str = field(default_factory=lambda: uuid.uuid4().hex[:8])

@dataclass
class EvolutionPhase:
    name: str
    summary: str

@dataclass
class SkillDraft:
    name: str
    desc: str
    reason: str
    approved: bool = False
    id: str = field(default_factory=lambda: uuid.uuid4().hex[:8])

@dataclass
class EvolutionRun:
    date: str
    phases: list = field(default_factory=list)
    patch_ids: list = field(default_factory=list)
    routing_note: str = ""
    memory_note: str = ""
    skill_drafts: list = field(default_factory=list)
    id: str = field(default_factory=lambda: uuid.uuid4().hex[:8])

@dataclass
class EvolutionSettings:
    cron: str = "0 2 * * *"
    auto_apply_l01: bool = True
    require_approval_l2: bool = True
    enabled: bool = True

@dataclass
class EvolutionStore:
    patches: list = field(default_factory=list)
    runs: list = field(default_factory=list)
    settings: EvolutionSettings = field(default_factory=EvolutionSettings)

    @classmethod
    def load(cls, path=None):
        path = path or EVOLUTION_PATH
        if not path.exists():
            return cls()
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except (json.JSONDecodeError, OSError):
            return cls()
        return cls(
            patches=[BehaviorPatch(**p) for p in data.get("patches", [])],
            runs=[EvolutionRun(**{**r, "phases": [EvolutionPhase(**p) for p in r.get("phases", [])], "skill_drafts": [SkillDraft(**d) for d in r.get("skill_drafts", [])]}) for r in data.get("runs", [])],
            settings=EvolutionSettings(**data.get("settings", {})),
        )

    def save(self, path=None):
        path = path or EVOLUTION_PATH
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps({"patches": [asdict(p) for p in self.patches], "runs": [{**asdict(r), "phases": [asdict(p) for p in r.phases], "skill_drafts": [asdict(d) for d in r.skill_drafts]} for r in self.runs], "settings": asdict(self.settings)}, ensure_ascii=False, indent=2), encoding="utf-8")

    def active_patch_rules(self):
        return [p.content for p in self.patches if p.status == "active"]

def run_evolution(store, stats=None, manual=True):
    stats = stats or {}
    today = time.strftime("%Y-%m-%d %H:%M:%S")
    if manual:
        log_activity("learn", "evolution started")
        append_audit("evolution", "start evolution", "confirmed")
    exist = {p.title for p in store.patches}
    fresh = [p for p in PATCH_POOL if p["title"] not in exist][:2]
    new_patches = [BehaviorPatch(**p, date=today[:10], status=("active" if p["level"] == "L0" and store.settings.auto_apply_l01 else "pending")) for p in fresh]
    drafted = {d.name for r in store.runs for d in r.skill_drafts}
    skills = ([SkillDraft(**SKILL_POOL[0])] if not drafted else [SkillDraft(**k) for k in SKILL_POOL if k["name"] not in drafted][:1])
    if len(store.runs) % 2 == 0:
        skills = []
    run = EvolutionRun(date=today, patch_ids=[p.id for p in new_patches], routing_note="note", memory_note="note", skill_drafts=skills, phases=[EvolutionPhase(n, "s") for n in PHASES])
    store.runs.insert(0, run)
    store.patches = new_patches + store.patches
    store.save()
    log_activity("learn", f"evolution done: {len(new_patches)} patches")
    return run

def set_patch(store, patch_id, status, verb):
    patch = next((p for p in store.patches if p.id == patch_id), None)
    if patch is None or status not in ("active", "disabled", "rolledback"):
        return False
    patch.status = status
    store.save()
    log_activity("learn", f"patch {patch.title} {verb}")
    append_audit("user", f"{verb} patch {patch.title}", "denied" if status == "rolledback" else "confirmed")
    return True

