    headers = {"Authorization": f"Bearer {api_key}"} if api_key.strip() else {}
    async with httpx.AsyncClient(timeout=timeout, headers=headers) as client:
        try:
            resp = await client.get(base + "/models")
            if resp.status_code < 400:
                data = resp.json()
                models = [m["id"] for m in data.get("data", [])]
                return {"kind": "openai", "models": models}
            if resp.status_code in (401, 403) and not headers:
                return {"kind": "unknown", "models": [],
                        "error": "端点要求鉴权，请先填入 API Key 再识别"}
            if resp.status_code in (401, 403):
                return {"kind": "unknown", "models": [],
                        "error": f"鉴权失败（HTTP {resp.status_code}），请检查 API Key"}
        except Exception:  # noqa: BLE001 — fall through to ollama sniff
