    path = Path(proj.path)
    try:
        if sys.platform == "darwin":
            subprocess.run(["open", str(path)], check=True, timeout=5)
        elif sys.platform == "win32":
            subprocess.run(["explorer", str(path)], check=True, timeout=5)
        else:
