def resolve(self, cid: str, approved: bool) -> bool:
    with self._lock:
        ev = self._pending.get(cid)
        if ev is None:
            return False
        self._decisions[cid] = approved
    ev.set()
    return True

def cancel_all(self) -> int:
    """Reject every pending confirm so a stopped run can unwind."""
    with self._lock:
        ids = list(self._pending)
        for cid in ids:
            self._decisions[cid] = False
            self._pending[cid].set()
    return len(ids)

    threading.Thread(target=self._run_chat, args=(text,), daemon=True).start()
    return True

def stop(self) -> bool:
    """Interrupt the in-flight chat (or lead) from the UI stop button."""
    with self._lock:
        if not self._busy:
            return False
        self._cancel.set()
        loop = self._loop
    self.confirmer.cancel_all()
    if loop is not None and loop.is_running():
        def _cancel_all() -> None:
            for task in asyncio.all_tasks(loop):
                task.cancel()

        try:
            loop.call_soon_threadsafe(_cancel_all)
        except RuntimeError:
            pass
    return True

def _run_chat(self, text: str) -> None:
    stopped = False
    try:
        if self._cancel.is_set():
            stopped = True
            return
        provider, decision = self._provider_for_message(text)
        if self._cancel.is_set():
            stopped = True
            return
        if decision["strategy"] == "默认直连":
            if self._agent is None:
                self._push("status", text="正在连接模型…")
                self._agent = self._build_agent()
            agent = self._agent
        else:
            self._push("status",
                       text=f"路由：{decision['taskType']} → {decision['chosen']}")
            agent = self._build_agent_with(provider)
        if self._cancel.is_set():
            stopped = True
            return

        async def _go() -> str:
            self._loop = asyncio.get_running_loop()
            try:
                return await agent.run(text)
            finally:
                self._loop = None

        try:
            answer = asyncio.run(_go())
        except asyncio.CancelledError:
            stopped = True
            return
        if self._cancel.is_set():
            stopped = True
            return
        proj = self.projects.get(self.projects.active)
        if proj is not None and self._conv_id:
            append_message(proj, self._conv_id, "assistant", answer)
        self._push("done", text=answer)
        self._speak(answer)
    except Exception as exc:  # noqa: BLE001 — surface to the UI
        if self._cancel.is_set():
            stopped = True
            return
        log.exception("chat failed")
        self._push("error", text=self._diagnose(exc))
    finally:
        with self._lock:
            self._busy = False
        if stopped:
            proj = self.projects.get(self.projects.active)
            if proj is not None and self._conv_id:
                append_message(proj, self._conv_id, "assistant", "（已停止）")
            self._push("stopped", text="已停止")

