    if resolved is None:
        return ref
    kind, kwargs = resolved
    if kind in ("local", "local_openai"):
        return f"{kwargs['model']}（本地）"
    am = next((m for m in self.api_models if m.id == ref[4:]), None)
    return am.display if am else ref

