"""Agent tools for the CodeCoreAgent knowledge vault (Obsidian / LLM Wiki)."""

from __future__ import annotations

from pathlib import Path
from typing import Any

from codeagent.knowledge import (
    KnowledgeConfig,
    ingest_text,
