    root = VideoOpsConfig.load().workspace()
    if not root.exists():
        return {"ok": False, "error": "路径不存在，请先一键布置"}
    try:
        if sys.platform == "darwin":
            subprocess.Popen(["open", str(root)])
        elif sys.platform == "win32":
