@staticmethod
def _as_int(value, default, lo, hi):
    try:
        n = int(value)
    except (TypeError, ValueError):
        n = default
    return max(lo, min(hi, n))

def send(self, text, resolution="720p", num_frames=60, num_inference_steps=50):
    text = (text or "").strip()
    if not text and not self._attachments:
        return False
    with self._lock:
        if self._busy:
            return False
        self._busy = True
        self._cancel.clear()
    video_ep = self._active_video_ep()
    video_prompt = text
    if video_ep is not None:
        threading.Thread(
            target=self._run_video_gen,
            args=(video_prompt, resolution or "720p",
                  self._as_int(num_frames, 60, 33, 81),
                  self._as_int(num_inference_steps, 50, 20, 50)),
            daemon=True,
        ).start()
        return True
    threading.Thread(target=self._run_chat, args=(text,), daemon=True).start()
    return True

def _run_video_gen(self, prompt, resolution, num_frames, num_inference_steps):
    from codeagent.videoops.gradio import generate_wan_video
    ep = self._active_video_ep()
    if ep is None:
        self._push("error", text="当前未选择文生视频模型")
        return
    dest = dest_dir / f"wan-{time_mod.strftime('%Y%m%d-%H%M%S')}.mp4"
    result = asyncio.run(generate_wan_video(
        ep.base, prompt, resolution=resolution,
        num_frames=num_frames, num_inference_steps=num_inference_steps, dest=dest,
    ))
    if not result.get("ok"):
        self._push("error", text=str(result.get("error") or "视频生成失败"))
        return
    self._push("done", text=answer)

