def _models_for_endpoint(self, ep: OllamaEndpoint) -> list[str]:
    """Names for the picker without waiting on the network."""
    names: list[str] = []
    if self._probe_cache is not None:
        names.extend(self._probe_cache[1].get(ep.id) or [])
    suffix = "@" + ep.id
    for mix in self.assets.mixtures:
        for ref in mix.members:
            if ref.startswith("local:") and ref.endswith(suffix):
                names.append(ref[6: -len(suffix)])
    if ep.kind == "gradio" and not names:
        names.append((ep.label or "").strip() or "WAN 文生视频")
    out: list[str] = []
    seen: set[str] = set()
    for raw in names:
        name = (raw or "").strip()
        if name and name not in seen:
            seen.add(name)
            out.append(name)
    return out

def _model_assets_payload(self, probe: bool) -> dict[str, Any]:
    by_id: dict[str, dict[str, Any]] = {}
    if probe:
        try:
            probed = asyncio.run(probe_all(self.assets.endpoints))
            by_id = {e["id"]: e for e in probed["endpoints"]}
            import time as _time
            self._probe_cache = (
                _time.monotonic(),
                {e["id"]: list(e.get("models") or []) for e in probed["endpoints"]},
            )
        except Exception:  # noqa: BLE001 — picker must still open
            log.debug("model-asset probe failed")
    endpoints: list[dict[str, Any]] = []
    for e in self.assets.endpoints:
        rec = {
            **by_id.get(e.id, {"id": e.id, "ok": False, "models": []}),
            "label": e.label, "role": e.role, "base": e.base,
        }
        rec["kind"] = rec.get("kind") or e.kind
        live = rec.get("models") or []
        if live and live and isinstance(live[0], dict):
            live = [m.get("name") or "" for m in live]
        stored = self._models_for_endpoint(e)
        merged: list[str] = []
        seen: set[str] = set()
        for name in list(live) + stored:
            name = str(name).strip()
            if name and name not in seen:
                seen.add(name)
                merged.append(name)
        rec["models"] = merged
        endpoints.append(rec)
    return {
        "endpoints": endpoints,
        "api_models": [self._api_model_dict(m) for m in self.assets.api_models],
        "mixtures": [self._mixture_dict(x) for x in self.assets.mixtures],
        "active": self.assets.active,
        "active_label": self._active_label(),
    }

