from pathlib import Path
from codeagent.tools.base import Tool
from codeagent.security.policy import RiskLevel

class UseSkillTool(Tool):
    name = "use_skill"
    description = "Load skill packs by name"
    parameters = {"type": "object", "properties": {"names": {"type": "array", "items": {"type": "string"}}, "name": {"type": "string"}}}
    risk_level = RiskLevel.READ_ONLY
    def __init__(self, library, activate=None):
        self.library = library
        self._activate = activate
    async def execute(self, names=None, name=None, **_):
        wanted = []
        if isinstance(name, str) and name.strip():
            wanted.append(name.strip())
        if isinstance(names, list):
            wanted.extend(str(x).strip() for x in names)
        found = []
        missing = []
        for raw in wanted:
            skill = self.library.get(raw)
            if skill is None:
                missing.append(raw)
            else:
                found.append(skill)
        if self._activate is not None and found:
            self._activate([s.name for s in found])
        parts = []
        for skill in found:
            parts.append(f"### Skill: {skill.name}\n{skill.content.strip()}")
        if missing:
            parts.append("missing: " + ", ".join(missing))
        return "\n\n".join(parts) or "catalog empty"

def workspace_skill_hints(root=None, extra=""):
    parts = [extra] if extra else []
    if root is None:
        return " ".join(parts)
    path = Path(root).expanduser()
    if not path.is_dir():
        return " ".join(parts)
    try:
        for item in path.rglob("*"):
            if item.is_file():
                parts.append(item.suffix.lower())
    except OSError:
        return " ".join(parts)
    return " ".join(parts)

