async def probe_comfy(base: str, timeout: float = 3.0) -> dict[str, Any] | None:
    root = normalize_comfy_base(base)
    if not root:
        return None
    try:
        async with httpx.AsyncClient(timeout=timeout) as client:
            r = await client.get(root + "/system_stats")
            data = _json_body(r) if r.status_code < 400 else None
            if not _is_comfy_payload(data):
                r = await client.get(root + "/object_info/CheckpointLoaderSimple")
                data = _json_body(r) if r.status_code < 400 else None
            if not _is_comfy_payload(data):
                return None
            models: list[dict[str, str]] = []
            seen: set[str] = set()
            for folder, label in (
                ("checkpoints", "Checkpoint"),
                ("diffusion_models", "UNET"),
                ("loras", "LoRA"),
            ):
                try:
                    listed = await client.get(f"{root}/models/{folder}")
                except (httpx.HTTPError, OSError):
                    continue
                if listed.status_code >= 400:
                    continue
                for name in _names_from_folder(_json_body(listed)):
                    if name in seen:
                        continue
                    seen.add(name)
                    models.append({"name": name, "folder": folder, "label": label})
            if not models and isinstance(data, dict):
                for name in _ckpt_names_from_object_info(data):
                    models.append({"name": name, "folder": "checkpoints", "label": "Checkpoint"})
            return {
                "ok": True,
                "base": root,
                "info": data if isinstance(data, dict) else {},
                "models": models,
            }
    except (httpx.HTTPError, OSError, ValueError):
        return None

