def extract_symbols(py: Path) -> list[str]:
    try:
        text = py.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return []
    lines: list[str] = []
    if text.lstrip().startswith('"""') or text.lstrip().startswith("'''"):
        head = text.lstrip()[3:]
        end = head.find('"""') if text.lstrip().startswith('"""') else head.find("'''")
        if end > 0:
            first = head[:end].strip().splitlines()[0][:200]
            lines.append(f"- **模块**：{first}")
    for raw in text.splitlines():
        m = re.match(r"^(class|def|async def)\s+([A-Za-z_][A-Za-z0-9_]*)", raw)
        if not m:
            continue
        kind, name = m.group(1), m.group(2)
        if name.startswith("_"):
            continue
        prefix = "class" if kind == "class" else "def"
        lines.append(f"- `{prefix} {name}`")
    return lines
